// CSD_RATIONALE_BEGIN
// Root cause of the timeout: the previous attempt had 9 phases with 9+ loops,
// each carrying 5–6 invariants and compound decreases clauses, overwhelming the
// Dafny verifier in 30 s.
//
// Fix: collapse to exactly 2 simple while-loops, each with 6 straightforward
// invariants and a single-variable decreases clause.
//
// Phase 1 – UnconstrainedStep loop: generate free text until RenderedEndsWith
//   detects "<<" (then EnterObservedConstrainedSpan, which leaves generated
//   unchanged and sets currentConstrainedOut := []) or EOS or budget.
// Phase 2 – Constrained loop: each iteration first calls CloseSpanIfComplete
//   (cost +0 if not done, +1 if done), then (if not done) ConstrainedStep (+1)
//   + AppendConstrainedToken (+0).  The model is primed by AppendTaskGuidance
//   to emit <<EXPR>> with a multi-variable expression.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedStep loop): the loop condition requires
//     !insideConstrainedOut, so the implication is vacuously true in every
//     iteration body. EnterObservedConstrainedSpan sets currentConstrainedOut
//     := [] and parser.IsValidPrefix([]) holds by the method precondition;
//     the loop exits immediately after because insideConstrainedOut becomes true.
//
//   Phase 2 (CloseSpanIfComplete + ConstrainedStep loop): when closed = true
//     the helper postcondition gives !insideConstrainedOut ==>
//     currentConstrainedOut == [] (vacuous implication true) and we break.
//     When closed = false the state is unchanged (no-op) so the invariant
//     holds from the previous iteration. ConstrainedStep returns a hard-masked
//     parser-valid token; AppendConstrainedToken's postcondition preserves
//     parser.IsValidPrefix(currentConstrainedOut). EOS path leaves state
//     unchanged. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//   Phase 1: UnconstrainedStep costs +1 (steps += 1). EOS: generated unchanged,
//     so |generated| <= |generatedPrefix| + (steps−1) <= |generatedPrefix| + steps ✓.
//     Non-EOS: generated grows by exactly 1 token and steps grew by 1 ✓.
//     EnterObservedConstrainedSpan costs +0 and leaves generated unchanged ✓.
//   Phase 2: CloseSpanIfComplete costs +1 when closed (steps += 1, generated
//     grows by at most 1 for ">>" delimiter) ✓. When not closed (cost +0),
//     ConstrainedStep costs +1 (steps += 1). EOS: generated unchanged ✓.
//     Non-EOS: AppendConstrainedToken grows generated by 1 and steps grew by 1 ✓.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. State your final answer as: The answer is <<EXPR>> where EXPR is a complete arithmetic expression that combines ALL relevant named variables with operators +, -, *, /, int(). Example: <<n * price - discount>> or <<int(n * frac) + base>>. Do not write a single variable name alone inside the angle brackets.");

var steps: nat := 0;

// Phase 1: Free generation until "<<" detected or EOS or budget
while steps < maxSteps && !insideConstrainedOut
  invariant steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 2: Constrained generation; close when complete
while insideConstrainedOut && steps < maxSteps
  invariant steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed {
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrainedOut, eosToken);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

cost := steps;

